def audit(E):
 O=E/'independent_choice_audit_004';O.mkdir(exist_ok=False)
 release=json.loads((E/'release.json').read_text());truth=json.loads((E/'evaluation_only/truth.json').read_text());summary=json.loads((E/'summary.json').read_text());arrival=json.loads((E/'independent_audit_003/report.json').read_text());observations=list(map(json.loads,(E/'perception.jsonl').open()));execution=list(map(json.loads,(E/'execution.jsonl').open()));positive=release['episode']['positive'];rows=[]
 for p in observations:
  nodes=[n for n in p['nodes'] if n['category']==truth['category']];distances=[float(np.linalg.norm(np.asarray(n['center'][:2])-truth['center_xy'])) for n in nodes];nearest=nodes[int(np.argmin(distances))]['node_id'] if distances and min(distances)<=2.5 else None
  correct_id=nearest if positive else None
  candidate_ids=[n['node_id'] for n in p['candidates']];proposal=candidate_ids[0] if candidate_ids else None;locked=p['selected_node_id'];locked_state=p['lock']['state_after']=='LOCKED'
  rows.append(dict(sensor_frame=p['sensor_frame'],frame_idx=p['frame_idx'],time_s=p['sim_time_s'],candidate_count=len(candidate_ids),candidate_contains_correct_target=bool(positive and correct_id is not None and correct_id in candidate_ids),first_proposal_node_id=proposal,first_proposal_correct=bool(positive and proposal is not None and proposal==correct_id),locked_node_id=locked,stable_lock_state=locked_state,correct_stable_lock=bool(positive and locked_state and locked is not None and locked==correct_id),wrong_stable_lock=bool(locked_state and locked is not None and (not positive or locked!=correct_id)),target_route_generated=bool(p['path_world'] and p['path_purpose']=='target_approach'),evaluated_nearest_predicted_node_id=correct_id,positive_task=positive))
