 p=argparse.ArgumentParser();p.add_argument('--episode',required=True);a=p.parse_args();e=R/'carla_official'/a.episode;report=audit(e);print(json.dumps({k:report[k] for k in ['episode','condition','first_proposal_correct_ever','correct_stable_lock_ever','strict_safe_arrival','no_match_correct_refusal']},ensure_ascii=False))
